use gateway_tacplus::types::services::oauth::{
    AuthorizeRequest, CallbackRequest, LogoutRequest,
};

// Sentinel
use gateway_tacplus::types::services::sentinel::sentinel::sentinel_service_client::SentinelServiceClient;

// Kernel (Mint — gateway delegates TokenMint/X509Mint to kernel)
